-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the wellcontrol capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- wellcontrol / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book wellcontrol refused: wellcontrol/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '3cb757188b7cdf8fd3be6307320c2c1c' and fields = '[{"key": "slant_string_volume_m3", "tol": 0.0005, "unit": "m3", "label": "String volume", "expected": 26.0836036552257}, {"key": "slant_annulus_volume_m3", "tol": 0.0005, "unit": "m3", "label": "Annulus volume", "expected": 72.46894410089696}, {"key": "slant_strokes_to_bit", "tol": 0.05, "unit": "strokes", "label": "Strokes to bit", "expected": 2173.6336379354752}, {"key": "slant_bottoms_up_strokes", "tol": 0.05, "unit": "strokes", "label": "Bottoms up strokes", "expected": 6039.078675074747}, {"key": "slant_tvd_at_bit_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the bit", "expected": 2507.9196993011733}, {"key": "slant_tvd_at_shoe_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the shoe", "expected": 1282.248590310811}]'::jsonb then 'old'
              when md5(prompt) = '6037d6172790a946a52ff33c7c2dd055' and fields = '[{"key": "slant_string_volume_m3", "tol": 0.0005, "unit": "m3", "label": "String volume", "expected": 26.0836036552257}, {"key": "slant_annulus_volume_m3", "tol": 0.0005, "unit": "m3", "label": "Annulus volume", "expected": 72.46894410089696}, {"key": "slant_strokes_to_bit", "tol": 0.05, "unit": "strokes", "label": "Strokes to bit", "expected": 2173.6336379354752}, {"key": "slant_bottoms_up_strokes", "tol": 0.05, "unit": "strokes", "label": "Bottoms up strokes", "expected": 6039.078675074747}, {"key": "slant_tvd_at_bit_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the bit", "expected": 2507.9196993011733}, {"key": "slant_tvd_at_shoe_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the shoe", "expected": 1282.248590310811}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book wellcontrol refused: wellcontrol/beginner matches neither its published form (prompt md5 3cb757188b7cdf8fd3be6307320c2c1c) nor its W1 form (prompt md5 6037d6172790a946a52ff33c7c2dd055), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 open-book wellcontrol: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book wellcontrol refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six numbers, and every one of them comes out of a span walk down the string and back up the annulus. The lessons did this on the HORIZONTAL well. This is the SLANT one, so none of your answers is a number a lesson printed. Report: (1) the total STRING volume in cubic metres; (2) the total ANNULUS volume in cubic metres; (3) the STROKES TO BIT at 0.012 m3 per stroke; (4) the BOTTOMS UP stroke count, which is the annulus rather than the whole system; (5) the TRUE VERTICAL DEPTH at the bit; and (6) the TRUE VERTICAL DEPTH at the shoe. Fields 1 to 4 use MEASURED depth because fluid fills the hole along its length. Fields 5 and 6 are vertical because the next tier turns them into pressures. Mixing the two is the classic error in this subject.',
           fields = '[{"key": "slant_string_volume_m3", "tol": 0.0005, "unit": "m3", "label": "String volume", "expected": 26.0836036552257}, {"key": "slant_annulus_volume_m3", "tol": 0.0005, "unit": "m3", "label": "Annulus volume", "expected": 72.46894410089696}, {"key": "slant_strokes_to_bit", "tol": 0.05, "unit": "strokes", "label": "Strokes to bit", "expected": 2173.6336379354752}, {"key": "slant_bottoms_up_strokes", "tol": 0.05, "unit": "strokes", "label": "Bottoms up strokes", "expected": 6039.078675074747}, {"key": "slant_tvd_at_bit_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the bit", "expected": 2507.9196993011733}, {"key": "slant_tvd_at_shoe_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the shoe", "expected": 1282.248590310811}]'::jsonb
     where app_slug = 'wellcontrol' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book wellcontrol refused: wellcontrol/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '6037d6172790a946a52ff33c7c2dd055' and fields = '[{"key": "slant_string_volume_m3", "tol": 0.0005, "unit": "m3", "label": "String volume", "expected": 26.0836036552257}, {"key": "slant_annulus_volume_m3", "tol": 0.0005, "unit": "m3", "label": "Annulus volume", "expected": 72.46894410089696}, {"key": "slant_strokes_to_bit", "tol": 0.05, "unit": "strokes", "label": "Strokes to bit", "expected": 2173.6336379354752}, {"key": "slant_bottoms_up_strokes", "tol": 0.05, "unit": "strokes", "label": "Bottoms up strokes", "expected": 6039.078675074747}, {"key": "slant_tvd_at_bit_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the bit", "expected": 2507.9196993011733}, {"key": "slant_tvd_at_shoe_m", "tol": 0.0005, "unit": "m", "label": "True vertical depth at the shoe", "expected": 1282.248590310811}]'::jsonb) from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book wellcontrol refused: wellcontrol/beginner does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book wellcontrol: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
